/** Stable 16-character Foundry document IDs for the compiled rulebook compendium. */
export const RULEBOOK_PACK='arcade-rulebook';
export const RULEBOOK_ENTRY_ID='pfaArcadeRules01';
export function rulePageId(key){const A='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';let h1=0x811c9dc5,h2=0x1b873593;for(const ch of String(key)){const c=ch.codePointAt(0);h1=Math.imul(h1^c,16777619)>>>0;h2=Math.imul(h2^c,2246822507)>>>0;}let out='';for(let i=0;i<16;i++){const v=i%2?h1:h2;out+=A[(v>>>((i*3)%27))%62];if(i%4===3){h1=Math.imul(h1^h2,2654435761)>>>0;h2=Math.imul(h2+i,1597334677)>>>0;}}return out;}
export const RULEBOOK_CHAPTERS = [
 {id:'welcome',title:'Welcome to the Fantasy Arcade',html:`<p>The Fantasy Arcade is a system-agnostic collection of 73 playable tavern games, casino tables, puzzles, performances and tactical arena contests for Foundry VTT. Every game runs on the GM’s client, uses <b>imaginary points only</b> and never changes your characters’ sheets, gold or items.</p><h3>Opening the arcade</h3><ul><li>Click the <b>Fantasy Arcade</b> button in the lower-left corner of the screen, or run <code>game.pactsFantasyArcade.open()</code>.</li><li>A GM must be connected: the GM’s client is the table’s referee.</li></ul><h3>Starting a table</h3><ol><li>Pick a game in the library. Each game page shows its art, a guided lesson and these rules.</li><li>Press <b>Create a multiplayer table</b>. Other players see it under <em>Active tables</em> and can <b>Join</b>.</li><li>The GM can add <b>AI opponents</b> (they play themselves) or <b>GM-controlled NPCs</b> (the GM plays them). The GM can switch an NPC between the two at any time.</li><li>Press <b>Start match</b>. Two-player shared games automatically add an AI rival if you start alone.</li></ol><h3>Kinds of table</h3><ul><li><b>Independent challenges</b> — everyone plays their own copy and compares scores (most dice, tavern and festival games).</li><li><b>Shared tables</b> — turn-by-turn games on one board (cards, board games, arenas).</li><li><b>Co-operative puzzles</b> — the whole party moves the same mechanism; players may join mid-puzzle.</li></ul>`},
 {id:'gm-tools',title:'GM Tools: Packs, Tournaments & Scenes',html:`<h3>GM Pack Studio</h3><p>Create world-saved content packs: Trivia (4–80 questions), Story scenes for Ispin’s Impossible Tale (4–80), Rune doors (4–80), a Three-Dragon Slots configuration, and linked Puzzle books (1–24 nodes). Select a pack in the library before creating its table.</p><h3>Puzzle Forge</h3><p>Generate reproducible riddle books by seed and difficulty, then bind any puzzle to a scene <b>Region or Tile</b>. When a token enters the trigger the puzzle opens for that player; solving it can <b>reveal or hide a Tile</b> or <b>open or close a door Wall</b>. Only declarative effects are possible — no scripts are stored in packs.</p><h3>Tournament Hall</h3><p>Run 2-, 4- or 8-competitor single-elimination brackets for the card and board games and the 1v1 arena contests. Each pairing launches a real table; decisive results advance automatically, and the GM may adjudicate draws (recorded in the audit log).</p><h3>Character links</h3><p>In a lobby the GM may link a seat to a world Actor (Imagi-Nations, D&D 5e, Pathfinder 2e or Daggerheart). Links are read-only: luck games ignore them; three physical contests (Arm-Wrestling, Kattal’s Hammer, Darts) accept a modest +0 to +2 assistance, and arena games choose a fitting kit. Nothing on the sheet is ever changed.</p>`},
 {id:'arena-basics',title:'Arena Basics',html:`<p>All fourteen arena and performance games share one tactical engine on a 9×7 grid.</p><ul><li>${arenaCore}</li><li>${arenaDamage}</li><li><b>Terrain:</b> pillars block movement and line of sight · cover gives +2 defence · spotlights add +3 to performances · slime drains stamina · hazards and pit traps deal damage.</li><li><b>Line of sight</b> is required for spells, ranged attacks and performances.</li><li><b>NPC difficulty</b> (set by the GM in the lobby): 1 Casual, 2 Skilled, 3 Tactical lookahead.</li><li>The GM can <b>pause</b> an arena, take over an NPC mid-bout, or hand it back to the AI.</li></ul>`},
 {id:'fair-play',title:'Fair Play & Credits',html:`<p>All stakes are fictional points; the arcade must never be used for real money or valuable property. Foundry module sockets are not a secure channel, so play with people you trust.</p><p><b>Wyvern Chess</b> is a modified, unofficial Foundry adaptation of Wyvern Chess by DM Asmo / Pacts & Polyhedrals, used under the Wyvern Chess Community License (see <code>licenses/WYVERN-CHESS-LICENSE.md</code>).</p><p>Fantasy Arcade © 2026 Asmo, Pacts & Polyhedrals (Ben Vale). Thanks to the playtesters and the Pacts & Polyhedrals, Blown Away and Imagi-Nations Discord communities.</p>`}
];

