const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const list=(items,tag='ul')=>`<${tag}>${items.map(x=>`<li>${e(x)}</li>`).join('')}</${tag}>`;
/** Shared HTML used by both the in-app rules panel and the compiled journal pages. */
export function rulesHTML(id,{image=null}={}){
 const r=GAME_RULES[id];if(!r)return '<p>Rules are not available for this activity.</p>';
 return `${image?`<p class="pfa-rules-art"><img src="${e(image)}" alt="${e(r.title)} cover art" width="320"/></p>`:''}<p class="pfa-rules-tagline"><em>${e(r.tagline||'')}</em></p><p>${e(r.summary)}</p>`+
  `<h3>At a glance</h3><ul><li><b>Players:</b> ${e(r.players)}</li><li><b>Length:</b> ${e(r.length)}</li><li><b>Goal:</b> ${e(r.objective)}</li></ul>`+
  `<h3>Setup</h3>${list(r.setup)}<h3>On your turn</h3>${list(r.turn,'ol')}<h3>Scoring</h3>${list(r.scoring)}<h3>End of the game</h3><p>${e(r.end)}</p>`+
  (r.character?`<h3>Linked characters</h3><p>${e(r.character)}</p>`:'')+(r.gm?`<h3>GM notes</h3><p>${e(r.gm)}</p>`:'')+`<h3>Tips</h3>${list(r.tips)}`;
}
